"use client";
import { useEffect, useRef } from "react";
import { cn } from "@/lib/utils";

type Particle = {
  tx: number;
  ty: number;
  ox: number;
  oy: number;
  d: number;
  sw: number;
  a: number;
  s: number;
  k: number;
};

// Particle geometry and scroll interpolation are ported from mailloop-footer-v6.html.
export function FooterWordmark({
  maxFontSize = 320,
  particlePaddingRatio = 0.5,
  className,
}: {
  maxFontSize?: number;
  particlePaddingRatio?: number;
  className?: string;
}) {
  const stageRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const stageElement = stageRef.current;
    const canvasElement = canvasRef.current;
    if (!stageElement || !canvasElement) return;
    const stage = stageElement;
    const cv = canvasElement;
    const context = cv.getContext("2d");
    if (!context) return;
    const ctx = context;
    const motion = matchMedia("(prefers-reduced-motion: reduce)");
    const hoverCapability = matchMedia("(hover: hover) and (pointer: fine)");
    const homeLink = stage.closest("a");
    let hovered =
      hoverCapability.matches && (homeLink?.matches(":hover") ?? false);
    let focused = homeLink?.matches(":focus-visible") ?? false;
    let active = hovered || focused;
    let pendingSweep = active;
    let sweepStart: number | null = null;
    let pausedAt: number | null = null;
    const sweepDuration = 1400;
    let disposed = false;
    let fontFamily = getComputedStyle(stage).fontFamily;
    let reduce = motion.matches;
    const TEXT = "mailloop";
    let W = 0,
      H = 0,
      CH = 0,
      pad = 0,
      fsz = 0,
      dpr = 1,
      parts: Particle[] = [],
      dust: string[] = [],
      smooth = 0,
      latestTarget = 0,
      visible = !window.IntersectionObserver,
      builtParticles = false,
      raf = 0,
      token = 0;
    let wm = { top: "", bottom: "", mid: "", edge: "" };
    const solid = document.createElement("canvas"),
      tmp = document.createElement("canvas"),
      sweepLayer = document.createElement("canvas");

    // Next's CSS optimizer may serialize the tokens as short/alpha hex.
    // Let Canvas parse CSS colors instead of assuming their source spelling.
    const palette = document.createElement("canvas");
    palette.width = palette.height = 1;
    const paletteContext = palette.getContext("2d", {
      willReadFrequently: true,
    })!;
    const channels = (color: string) => {
      paletteContext.clearRect(0, 0, 1, 1);
      paletteContext.fillStyle = color;
      paletteContext.fillRect(0, 0, 1, 1);
      return Array.from(paletteContext.getImageData(0, 0, 1, 1).data).slice(
        0,
        3,
      );
    };
    // theme colours come straight from the CSS variables of the active theme
    function readColors() {
      const cs = getComputedStyle(document.documentElement),
        v = (n: string) => cs.getPropertyValue(n).trim();
      const a = channels(v("--dust-a")),
        b = channels(v("--dust-b"));
      dust = Array.from({ length: 8 }, (_, i) => {
        const t = i / 7;
        return (
          "rgb(" +
          a.map((x, k) => Math.round(x + (b[k] - x) * t)).join(",") +
          ")"
        );
      });
      const shine = v("--wm-soft-sweep"),
        n = channels(shine);
      wm = {
        top: v("--wm-top"),
        bottom: v("--wm-bottom"),
        mid: shine,
        edge: "rgba(" + n[0] + "," + n[1] + "," + n[2] + ",0)",
      };
    }
    const setFont = (c: CanvasRenderingContext2D, s: number) => {
      c.font = "700 " + s + "px " + fontFamily;
      if ("letterSpacing" in c) c.letterSpacing = -0.055 * s + "px";
    };

    // the plain, smooth gradient word (same look as the v3 wordmark), drawn once per size/theme
    function buildSolid() {
      if (!W) return;
      solid.width = tmp.width = sweepLayer.width = W * dpr;
      solid.height = tmp.height = sweepLayer.height = CH * dpr;
      const c = solid.getContext("2d")!;
      c.setTransform(dpr, 0, 0, dpr, 0, 0);
      c.clearRect(0, 0, W, CH);
      setFont(c, fsz);
      c.textAlign = "center";
      c.textBaseline = "alphabetic";
      const g = c.createLinearGradient(0, pad, 0, pad + fsz * 0.9);
      g.addColorStop(0, wm.top);
      g.addColorStop(1, wm.bottom);
      c.fillStyle = g;
      c.fillText(TEXT, W / 2, pad + fsz * 0.76);
    }

    async function build() {
      const my = ++token;
      try {
        await document.fonts.load("700 100px " + fontFamily);
      } catch {
        /* Use the app fallback if the font cannot load. */
      }
      if (disposed || my !== token) return;
      W = Math.floor(stage.clientWidth);
      if (!W) return;
      const probe = document.createElement("canvas").getContext("2d")!;
      setFont(probe, 100);
      fsz = Math.min(
        maxFontSize,
        ((W * 0.98) / probe.measureText(TEXT).width) * 100,
      );
      H = Math.round(fsz * 0.98);
      pad = Math.round(H * particlePaddingRatio); // empty room above the word for dust to float in
      CH = H + pad;
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      cv.width = W * dpr;
      cv.height = CH * dpr;
      cv.style.height = CH + "px";

      buildSolid();
      parts = [];
      builtParticles = false;
      if (visible) buildParticles();
      render(performance.now(), true);
      schedule();
    }

    function buildParticles() {
      const off = document.createElement("canvas");
      off.width = W;
      off.height = CH;
      const o = off.getContext("2d", { willReadFrequently: true })!;
      setFont(o, fsz);
      o.fillStyle = dust[0]; // Only alpha is sampled; use an opaque theme color.
      o.textAlign = "center";
      o.textBaseline = "alphabetic";
      o.fillText(TEXT, W / 2, pad + fsz * 0.76);
      const data = o.getImageData(0, 0, W, CH).data;
      let step = Math.max(2, Math.round(W / 380));
      const limit = W < 640 ? 3000 : 5500;
      for (;;) {
        parts = [];
        for (let y = 0; y < CH; y += step)
          for (let x = 0; x < W; x += step) {
            if (data[(y * W + x) * 4 + 3] > 140) {
              const tx = x + (Math.random() - 0.5) * step * 0.6,
                ty = y + (Math.random() - 0.5) * step * 0.6;
              parts.push({
                tx,
                ty,
                ox: tx + (Math.random() - 0.5) * W * 0.5,
                oy: Math.random() * CH * 1.15 - CH * 0.05,
                d: Math.random() * 0.3 + (tx / W) * 0.15,
                sw: (Math.random() - 0.5) * 90,
                a: 0.55 + Math.random() * 0.45,
                s: step * (0.6 + Math.random() * 0.5),
                k: Math.max(
                  0,
                  Math.min(7, Math.floor(((ty - pad) / (fsz * 0.8)) * 8)),
                ),
              });
            }
          }
        if (parts.length <= limit) break;
        step++;
      }
      parts.sort((a, b) => a.k - b.k);
      builtParticles = true;
    }

    function progress() {
      if (reduce) return 1;
      const r = stage.getBoundingClientRect();
      return Math.max(0, Math.min(1, (innerHeight - r.top) / (r.height + 16)));
    }

    function render(t: number, snap = false) {
      if (!parts.length) {
        if (reduce && W) {
          ctx.setTransform(1, 0, 0, 1, 0, 0);
          ctx.clearRect(0, 0, cv.width, cv.height);
          ctx.drawImage(solid, 0, 0);
          cv.dataset.wordmarkState = "idle";
        }
        return;
      }
      const target = progress();
      latestTarget = target;
      smooth = snap ? target : smooth + (target - smooth) * 0.1;
      // Exponential interpolation otherwise never reaches the assembled state.
      if (target === 1 && smooth > 0.9999) smooth = 1;
      const p = smooth;
      const u = Math.max(0, Math.min(1, (p - 0.86) / 0.14)),
        s = u * u * (3 - 2 * u); // dust -> smooth word crossfade

      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, W, CH);

      if (s < 1) {
        // dust assembling
        let k = -1;
        for (let i = 0; i < parts.length; i++) {
          const q0 = parts[i],
            q = Math.max(0, Math.min(1, (p - q0.d) / 0.55));
          if (q <= 0) continue;
          const e = 1 - Math.pow(1 - q, 3),
            swirl = Math.sin(q * Math.PI) * q0.sw;
          const x = q0.ox + (q0.tx - q0.ox) * e + swirl,
            y = q0.oy + (q0.ty - q0.oy) * e;
          if (q0.k !== k) {
            k = q0.k;
            ctx.fillStyle = dust[k];
          }
          ctx.globalAlpha = Math.min(1, q * 2.2) * q0.a * (1 - s);
          ctx.fillRect(x, y, q0.s, q0.s);
        }
        ctx.globalAlpha = 1;
      }

      if (s === 0 && cv.dataset.wordmarkState !== "assembling") {
        cv.dataset.wordmarkState = "assembling";
      }
      if (s > 0) {
        // finished word: plain gradient + shine sweep
        const c = tmp.getContext("2d")!;
        c.setTransform(1, 0, 0, 1, 0, 0);
        c.globalCompositeOperation = "source-over";
        c.clearRect(0, 0, tmp.width, tmp.height);
        c.drawImage(solid, 0, 0);
        const assembled = p === 1;
        if (sweepStart !== null && t - sweepStart >= sweepDuration) {
          sweepStart = null;
        }
        if (
          assembled &&
          visible &&
          pendingSweep &&
          !reduce &&
          sweepStart === null
        ) {
          sweepStart = t;
          pendingSweep = false;
        }
        const highlight = assembled && reduce && active;
        const sweeping = assembled && !reduce && sweepStart !== null;
        const state = !assembled
          ? "assembling"
          : highlight
            ? "highlight"
            : sweeping
              ? "sweeping"
              : "idle";
        if (cv.dataset.wordmarkState !== state)
          cv.dataset.wordmarkState = state;
        if (highlight || sweeping) {
          const phase = highlight ? 0.5 : (t - sweepStart!) / sweepDuration;
          const eased = phase * phase * (3 - 2 * phase);
          const cx = W * (-0.4 + 1.8 * eased);
          c.setTransform(dpr, 0, 0, dpr, 0, 0);
          const g = c.createLinearGradient(
            cx - W * 0.18,
            0,
            cx + W * 0.18,
            CH * 0.65,
          );
          g.addColorStop(0, wm.edge);
          g.addColorStop(0.5, wm.mid);
          g.addColorStop(1, wm.edge);
          // Mask the light with the faded glyphs before compositing it over
          // the word. This also brightens white glyphs in the neutral dark theme.
          const light = sweepLayer.getContext("2d")!;
          light.setTransform(1, 0, 0, 1, 0, 0);
          light.globalCompositeOperation = "source-over";
          light.clearRect(0, 0, sweepLayer.width, sweepLayer.height);
          light.drawImage(solid, 0, 0);
          light.setTransform(dpr, 0, 0, dpr, 0, 0);
          light.globalCompositeOperation = "source-in";
          light.globalAlpha = 0.9;
          light.fillStyle = g;
          light.fillRect(0, 0, W, CH);
          light.globalAlpha = 1;
          c.setTransform(1, 0, 0, 1, 0, 0);
          c.drawImage(sweepLayer, 0, 0);
        }
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.globalAlpha = s;
        ctx.drawImage(tmp, 0, 0);
        ctx.globalAlpha = 1;
      }
    }

    function updateInteraction() {
      const nextActive = hovered || focused;
      if (nextActive && !active && sweepStart === null) pendingSweep = true;
      if (!nextActive) pendingSweep = false;
      active = nextActive;
      render(performance.now());
      schedule();
    }
    const pointerEnter = (event: PointerEvent) => {
      hovered = event.pointerType !== "touch" && hoverCapability.matches;
      updateInteraction();
    };
    const pointerLeave = () => {
      hovered = false;
      updateInteraction();
    };
    const focus = () => {
      focused = homeLink?.matches(":focus-visible") ?? false;
      updateInteraction();
    };
    const blur = () => {
      focused = false;
      updateInteraction();
    };
    const pointerDown = (event: PointerEvent) => {
      if (event.pointerType === "touch") {
        hovered = focused = false;
        pendingSweep = false;
        sweepStart = null;
        updateInteraction();
      }
    };
    homeLink?.addEventListener("pointerenter", pointerEnter);
    homeLink?.addEventListener("pointerleave", pointerLeave);
    homeLink?.addEventListener("pointerdown", pointerDown);
    homeLink?.addEventListener("focus", focus);
    homeLink?.addEventListener("blur", blur);

    function schedule() {
      if (visible && !reduce && !document.hidden && builtParticles && !raf)
        raf = requestAnimationFrame(loop);
    }
    function loop(t: number) {
      raf = 0;
      render(t);
      if (Math.abs(latestTarget - smooth) > 0.0001 || sweepStart !== null)
        schedule();
    }
    const intersection = window.IntersectionObserver
      ? new IntersectionObserver(
          ([en]) => {
            const now = performance.now();
            if (!en.isIntersecting && visible) pausedAt = now;
            if (en.isIntersecting && pausedAt !== null) {
              if (sweepStart !== null) sweepStart += now - pausedAt;
              pausedAt = null;
            }
            visible = en.isIntersecting;
            if (!visible) {
              cancelAnimationFrame(raf);
              raf = 0;
            } else if (!builtParticles) {
              void build();
            } else {
              schedule();
            }
          },
          { rootMargin: "200px 0px" },
        )
      : null;
    intersection?.observe(stage);
    window.addEventListener("scroll", schedule, { passive: true });
    document.addEventListener("visibilitychange", schedule);

    let rz: ReturnType<typeof setTimeout> | undefined;
    const resize = new ResizeObserver(() => {
      if (Math.floor(stage.clientWidth) === W) return;
      clearTimeout(rz);
      rz = setTimeout(() => {
        void build();
      }, 120);
    });
    resize.observe(stage);
    const theme = new MutationObserver(() => {
      readColors();
      const nextFontFamily = getComputedStyle(stage).fontFamily;
      if (fontFamily !== nextFontFamily) {
        fontFamily = nextFontFamily;
        void build();
      } else {
        buildSolid();
        render(performance.now(), true);
        schedule();
      }
    });
    theme.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["data-theme", "data-appearance"],
    });
    const updateMotion = () => {
      reduce = motion.matches;
      sweepStart = null;
      pendingSweep = active;
      cancelAnimationFrame(raf);
      raf = 0;
      render(performance.now(), true);
      if (visible && !builtParticles) void build();
      else schedule();
    };
    motion.addEventListener("change", updateMotion);
    readColors();
    void build();
    return () => {
      disposed = true;
      ++token;
      intersection?.disconnect();
      resize.disconnect();
      theme.disconnect();
      clearTimeout(rz);
      cancelAnimationFrame(raf);
      window.removeEventListener("scroll", schedule);
      document.removeEventListener("visibilitychange", schedule);
      motion.removeEventListener("change", updateMotion);
      homeLink?.removeEventListener("pointerenter", pointerEnter);
      homeLink?.removeEventListener("pointerleave", pointerLeave);
      homeLink?.removeEventListener("pointerdown", pointerDown);
      homeLink?.removeEventListener("focus", focus);
      homeLink?.removeEventListener("blur", blur);
    };
  }, [maxFontSize, particlePaddingRatio]);
  return (
    <div
      aria-hidden="true"
      className={cn(
        "pointer-events-none mx-auto mt-[calc(-1*clamp(16px,4vw,52px))] max-w-[1180px] px-[clamp(24px,5vw,56px)] pb-[clamp(12px,2vw,24px)]",
        className,
      )}
    >
      <div ref={stageRef} className="relative w-full">
        <canvas ref={canvasRef} className="block w-full" />
      </div>
    </div>
  );
}
